from __future__ import annotations

import hashlib
import html
import re
from functools import lru_cache
from pathlib import Path
from typing import Callable

import yaml

from incident_copilot.models import EvidenceChunk, Section, SourceDocument


FRONTMATTER_DELIMITER = "---"
BOILERPLATE_LINES = {
    "Exported from Confluence",
    "Generated by Confluence",
    "Generated by internal wiki export",
}
HEADING_PATTERN = re.compile(r"^(#{1,6})\s+(.+?)\s*#*\s*$")
HTML_TAG_PATTERN = re.compile(r"<[^>]+>")
SENTENCE_PATTERN = re.compile(r"(?<=[.!?])\s+(?=[A-Z0-9`])")
TOKEN_PATTERN = re.compile(r"\w+|[^\w\s]", re.UNICODE)


def clean_markdown(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = html.unescape(text)
    text = re.sub(r"(?is)<script\b[^>]*>.*?</script\s*>", " ", text)
    text = re.sub(r"(?is)<style\b[^>]*>.*?</style\s*>", " ", text)
    text = re.sub(r"(?i)<br\s*/?>", "\n", text)
    text = re.sub(r"(?i)</(?:p|div|li|tr|h[1-6])\s*>", "\n", text)
    text = HTML_TAG_PATTERN.sub("", text)

    lines = []
    for line in text.splitlines():
        normalized = re.sub(r"[ \t]+", " ", line).strip()
        if normalized in BOILERPLATE_LINES:
            continue
        if re.fullmatch(r"Page\s+\d+\s+of\s+\d+", normalized, flags=re.IGNORECASE):
            continue
        lines.append(normalized)

    cleaned = "\n".join(lines)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
    return cleaned.strip()


def parse_markdown_document(path: Path, corpus_root: Path) -> SourceDocument:
    raw_bytes = path.read_bytes()
    text = raw_bytes.decode("utf-8", errors="strict")
    normalized = text.replace("\r\n", "\n").replace("\r", "\n")
    lines = normalized.splitlines()
    if not lines or lines[0].strip() != FRONTMATTER_DELIMITER:
        raise ValueError(f"{path} must start with YAML front matter")

    closing_index = next(
        (index for index in range(1, len(lines)) if lines[index].strip() == FRONTMATTER_DELIMITER),
        None,
    )
    if closing_index is None:
        raise ValueError(f"{path} has unclosed YAML front matter")

    metadata = yaml.safe_load("\n".join(lines[1:closing_index])) or {}
    if not isinstance(metadata, dict):
        raise ValueError(f"{path} YAML front matter must be a mapping")

    content = clean_markdown("\n".join(lines[closing_index + 1:]))
    first_heading = next((match.group(2) for line in content.splitlines()
                          if (match := HEADING_PATTERN.match(line)) and len(match.group(1)) == 1), path.stem)
    source_path = path.relative_to(corpus_root).as_posix()
    content_hash = hashlib.sha256(raw_bytes).hexdigest()
    return SourceDocument.from_parts(
        source_path=source_path,
        metadata=metadata,
        title=first_heading,
        content=content,
        content_hash=content_hash,
    )


def split_into_sections(document: SourceDocument) -> list[Section]:
    sections: list[Section] = []
    heading_stack: list[str] = []
    current_path: str | None = None
    current_lines: list[str] = []

    for line in document.content.splitlines():
        match = HEADING_PATTERN.match(line)
        if not match:
            current_lines.append(line)
            continue

        level = len(match.group(1))
        heading = match.group(2).strip()
        if level == 1:
            if current_path is not None:
                _append_section(sections, current_path, current_lines)
            elif current_lines:
                _append_section(sections, document.title, current_lines)
            heading_stack = [heading]
            current_path = None
            current_lines = []
            continue

        if current_path is not None:
            _append_section(sections, current_path, current_lines)
            current_lines = []

        heading_stack = heading_stack[:level - 1]
        heading_stack.append(heading)
        current_path = " / ".join(heading_stack[1:]) or heading
        current_lines.append(line)

    if current_path is not None:
        _append_section(sections, current_path, current_lines)
    elif current_lines:
        _append_section(sections, document.title, current_lines)

    if not sections and document.content:
        sections.append(Section(path=document.title, content=document.content))
    return sections


def chunk_document(
    document: SourceDocument,
    max_tokens: int = 450,
    overlap_tokens: int = 50,
    token_counter: Callable[[str], int] | None = None,
) -> list[EvidenceChunk]:
    if max_tokens < 1 or overlap_tokens < 0 or overlap_tokens >= max_tokens:
        raise ValueError("Require max_tokens > overlap_tokens >= 0")
    count_tokens = token_counter or model_token_count
    chunks: list[EvidenceChunk] = []
    for section in split_into_sections(document):
        units = _section_units(section.content, max_tokens, count_tokens)
        section_chunks = _pack_units(units, max_tokens, overlap_tokens, count_tokens)
        for chunk_content in section_chunks:
            chunk_index = len(chunks)
            chunk_id = f"{document.doc_id}:{document.version}:{chunk_index}"
            chunks.append(EvidenceChunk(
                chunk_id=chunk_id,
                doc_id=document.doc_id,
                source_path=document.source_path,
                section_path=section.path,
                service=document.service,
                environment=document.environment,
                version=document.version,
                status=document.status,
                owner=document.owner,
                last_reviewed=document.last_reviewed,
                source_type=document.source_type,
                content_hash=document.content_hash,
                chunk_index=chunk_index,
                content=chunk_content,
            ))
    return chunks


def model_token_count(text: str) -> int:
    try:
        import tiktoken
    except ImportError:
        return len(TOKEN_PATTERN.findall(text))

    return len(_embedding_encoding().encode(text))


@lru_cache(maxsize=1)
def _embedding_encoding():
    import tiktoken

    return tiktoken.get_encoding("cl100k_base")


def _append_section(sections: list[Section], path: str, lines: list[str]) -> None:
    content = "\n".join(lines).strip()
    if content:
        sections.append(Section(path=path, content=content))


def _section_units(section_text: str, max_tokens: int,
                   count_tokens: Callable[[str], int]) -> list[str]:
    units: list[str] = []
    for block in _paragraph_blocks(section_text):
        lines = block.splitlines()
        if lines and HEADING_PATTERN.match(lines[0]):
            units.append(lines[0])
            lines = lines[1:]
            block = "\n".join(lines).strip()
            if not block:
                continue

        if count_tokens(block) <= max_tokens or _is_fenced_code(block) or _is_table(block):
            units.append(block)
            continue
        if all(_is_list_item(line) for line in lines if line.strip()):
            for line in lines:
                if line.strip():
                    units.extend(_split_long_line(line, max_tokens, count_tokens)
                                 if count_tokens(line) > max_tokens else [line])
            continue
        sentences = [part.strip() for part in SENTENCE_PATTERN.split(block) if part.strip()]
        for sentence in sentences:
            if count_tokens(sentence) <= max_tokens:
                units.append(sentence)
            else:
                units.extend(_split_long_line(sentence, max_tokens, count_tokens))
    return units


def _paragraph_blocks(text: str) -> list[str]:
    blocks: list[str] = []
    current: list[str] = []
    fence: str | None = None

    def flush() -> None:
        nonlocal current
        block = "\n".join(current).strip()
        if block:
            blocks.append(block)
        current = []

    for line in text.splitlines():
        stripped = line.strip()
        fence_match = re.match(r"^(```|~~~)", stripped)
        if fence_match:
            marker = fence_match.group(1)
            if fence is None:
                flush()
                fence = marker
                current.append(line)
            elif marker == fence:
                current.append(line)
                flush()
                fence = None
            else:
                current.append(line)
            continue
        if fence is not None:
            current.append(line)
        elif stripped:
            current.append(line)
        else:
            flush()
    flush()
    return blocks


def _split_long_line(text: str, max_tokens: int,
                     count_tokens: Callable[[str], int]) -> list[str]:
    words = text.split()
    pieces: list[str] = []
    current: list[str] = []
    for word in words:
        candidate = " ".join(current + [word])
        if current and count_tokens(candidate) > max_tokens:
            pieces.append(" ".join(current))
            current = [word]
        else:
            current.append(word)
    if current:
        pieces.append(" ".join(current))
    return pieces


def _pack_units(units: list[str], max_tokens: int, overlap_tokens: int,
                count_tokens: Callable[[str], int]) -> list[str]:
    chunks: list[str] = []
    current: list[str] = []
    for unit in units:
        candidate = "\n\n".join(current + [unit])
        if current and count_tokens(candidate) > max_tokens:
            chunks.append("\n\n".join(current))
            overlap = _overlap_suffix(current, overlap_tokens, count_tokens)
            current = overlap + [unit]
            if count_tokens("\n\n".join(current)) > max_tokens:
                current = [unit]
        else:
            current.append(unit)
    if current:
        chunks.append("\n\n".join(current))
    return chunks


def _overlap_suffix(units: list[str], overlap_tokens: int,
                    count_tokens: Callable[[str], int]) -> list[str]:
    suffix: list[str] = []
    for unit in reversed(units):
        candidate = [unit] + suffix
        if count_tokens("\n\n".join(candidate)) > overlap_tokens:
            break
        suffix = candidate
    return suffix


def _is_fenced_code(text: str) -> bool:
    return text.startswith("```") or text.startswith("~~~")


def _is_list_item(line: str) -> bool:
    return bool(re.match(r"^\s*(?:[-*+]\s+|\d+[.)]\s+)", line))


def _is_table(text: str) -> bool:
    lines = [line for line in text.splitlines() if line.strip()]
    return bool(lines) and all(line.lstrip().startswith("|") for line in lines)
